# every whole-number rectangle with a perimeter of 24
print("width x height   perimeter   area")
for width in range(1, 12):
    height = 12 - width                 # width + height must be half of 24
    if width <= height:
        print(f"{width:>5} x {height:<5}   {2 * (width + height):>9}   {width * height:>4}")

# every whole-number rectangle with an area of 36
print("width x height   area   perimeter")
for width in range(1, 37):
    if 36 % width == 0 and width <= 36 // width:
        height = 36 // width
        print(f"{width:>5} x {height:<5}   {width * height:>4}   {2 * (width + height):>9}")
